  (* [comment removed for export] *)
  Fixpoint bloop (body : A -> A + B) (fuel : nat) (s : A) : option B :=
    match fuel with
    | O => None
    | S fu => match body s with inl s' => bloop body fu s' | inr r => Some r end
    end.

