  (* [comment removed for export] *)
  Fixpoint owloop (cond : A -> bool) (body : A -> option A) (fuel : nat) (s : A) : option A :=
    match fuel with
    | O => None
    | S fu => if cond s then match body s with Some s' => owloop cond body fu s' | None => None end else Some s
    end.

