Definition DSH (j k : Z) (x : list Z) : Prop :=
  (k = 0 -> (j = 0 -> znth x 0 = 0) /\ (1 <= j -> 10 ^ (j - 1) <= znth x 0 < 10 ^ j))
  /\ (1 <= k -> 10 ^ 8 <= znth x 0 < 10 ^ 9).

