(* [comment removed for export] *)
Definition LZI (f0 : shfile) (c : Z) (f : shfile) : Prop :=
  sh_wf f /\ sh_same f0 f /\ sh_rpos f0 <= sh_rpos f /\ (contc c -> sh_rpos f <= sh_N f) /\ bchar c.

