Definition rdist (k a : Z) : Z := (k - a) mod 2048.

Lemma land_MASK_mod : forall k, Z.land k MASK = k mod 2048.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00'^A").
Qed.

Lemma rdist_step_down : forall k a, 0 <= k < 2048 -> 0 <= a < 2048 -> k <> a ->
