(* [comment removed for export] *)
Definition shok (sh : Z) : Prop := sh = 1 \/ sh = 9.
Lemma sh_facts : forall sh, shok sh ->
  1 <= sh /\ Z.shiftl 1 sh - 1 = Z.ones sh /\ 1 <= Z.shiftr 1000000000 sh /\
  Z.shiftr 1000000000 sh * (2 ^ sh - 1) < 1000000000 /\ 0 < 2 ^ sh <= 512.
