  sh_wf f -> BB f -> bchar c -> (contc c -> sh_rpos f <= sh_N f) ->
  exists st, fs_inf_loop 9%nat (0, c, f) = Some st /\ PFI f 8 st /\ fs_inf_cond st = false.
