Lemma fs_par_total : forall fuel f,
  sh_wf f -> BB f -> 0 <= sh_rpos f -> zlength (sh_buf f) + 2 <= Z.of_nat fuel ->
  exists i c f', fs_par_loop fuel (1, f) = Some (i, c, f') /\ sh_wf f' /\ sh_same f f' /\ bchar c /\ 1 <= i
